from itertools import combinations
import json

def assess(attrs):
    required = ['price', 'admin', 'small_cap', 'large_cap'] + [f'replacement_{i}' for i in range(6)] + [f'refund_{i}' for i in range(6)]
    for k in required:
        if k not in attrs or attrs[k] is None:
            return {"feasible": False, "utility": None}
        if not isinstance(attrs[k], int) or attrs[k] < 0:
            return {"feasible": False, "utility": None}

    price = attrs['price']
    admin = attrs['admin']
    small_cap = attrs['small_cap']
    large_cap = attrs['large_cap']
    replacements = [attrs[f'replacement_{i}'] for i in range(6)]
    refunds = [attrs[f'refund_{i}'] for i in range(6)]

    if price > 1200000:
        return {"feasible": False, "utility": None}

    max_assessment = 0
    for n in range(0, 4):
        for S in combinations(range(6), n):
            if n == 0:
                assessment = 0
            else:
                rep_sum = sum(replacements[i] for i in S)
                ref_sum = sum(refunds[i] for i in S)
                if n <= 2:
                    cap = small_cap
                else:
                    cap = large_cap
                comp = min(ref_sum, cap)
                net = max(0, rep_sum - comp - 200000) + admin
                assessment = net
            if assessment > 200000:
                return {"feasible": False, "utility": None}
            if assessment > max_assessment:
                max_assessment = assessment

    utility = 2000000 - price - max_assessment
    return {"feasible": True, "utility": str(utility)}
